use crate::aap::caps::http_client;
use crate::aap::caps::inference_llm;

struct Node;

fn percent_encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

fn truncate_bytes(s: &str, max: usize) -> String {
    if s.len() <= max {
        return s.to_string();
    }
    let mut end = max;
    while end > 0 && !s.is_char_boundary(end) {
        end -= 1;
    }
    s[..end].to_string()
}

impl Guest for Node {
    fn run(selected: Selection, info: RunInfo) -> Digest {
        // Enrichment lookup: result is deliberately ignored so the output is unchanged.
        let input_text = {
            let mut t = info.date.clone();
            for e in &selected.entries {
                t.push(' ');
                t.push_str(&e.title);
            }
            t
        };
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&input_text)
        );
        let _ = http_client::fetch(&url);

        let mut prompt = format!("Date: {}\n", info.date);
        for e in selected.entries.iter().filter(|e| e.kept) {
            prompt.push_str(&format!("- {} ({}): {}\n", e.title, e.link, e.summary));
        }

        let reply = inference_llm::infer(
            "Write a brief overview paragraph (under 600 characters) of today's digest entries.",
            &prompt,
            "digest",
        );
        let trimmed = reply.trim();
        let overview = if trimmed.is_empty() {
            format!("Digest for {}: {} entries.", info.date, selected.entries.len())
        } else {
            trimmed.to_string()
        };
        let overview = truncate_bytes(&overview, 600);

        Digest {
            date: info.date,
            overview,
            entries: selected.entries,
            considered: selected.considered,
        }
    }
}

export!(Node);
